def validate(t,post,pub):
    if (int(post.get("id",0)),post.get("slug"),post.get("type"),post.get("status"),int(post.get("featured_media") or 0))!=(
        t["id"],t["slug"],"post","publish",t["cover"]):raise RuntimeError("Original identity/media mismatch")
    if not post["modified_gmt"].startswith(t["mod"]):raise RuntimeError("Post changed since human audit")
    seo=pub.get("yoast_head_json") or {}
    if seo.get("canonical")!=base.SITE+"/"+t["slug"]+"/" or (seo.get("robots") or {}).get("index")=="noindex" or not seo.get("og_image"):
        raise RuntimeError("Canonical/OG/index unexpected")
    original=post["content"]
    if len(original)<1700:raise RuntimeError("Original content truncated")
    imgs=re.findall(r"<img\\b[^>]*>",original,flags=re.I)
    if len(imgs)!=0:raise RuntimeError("Article contains in-body image, do not overwrite media")
    if len(t["html"])<2500 or t["html"].count("<h2>")<5 or t["html"].count("<a href=")<2:raise RuntimeError("New body fails quality checks")
    return seo
def main():
    todo=[]
    for t in TARGETS:
        old=base.bridge_post(t["id"]);pub=base.public_post(t["id"])
        if MARK+"-"+t["slug"] in old.get("content",""):
            print("SECOND50_ALREADY_UPDATED",old["link"],flush=True);continue
        validate(t,old,pub)
        content='<section id="'+MARK+'-'+t["slug"]+'" dir="rtl">'+t["html"]+'</section>'
        todo.append((t,old,pub,content))
        print("SECOND50_PREFLIGHT",t["id"],len(old["content"]),len(content),flush=True)
    print("SECOND50_ALL_PREFLIGHTS_PASSED",len(todo),flush=True)
    for t,old,pub0,content in todo:
        now=base.bridge_post(t["id"])
        if now.get("modified_gmt")!=old.get("modified_gmt") or now.get("content")!=old.get("content"):
            raise RuntimeError("Concurrent edit, abort")
        meta={"_yoast_wpseo_title":t["seo"],"_yoast_wpseo_metadesc":t["desc"],"_yoast_wpseo_focuskw":t["kw"],
              "_yoast_wpseo_opengraph-title":t["seo"],"_yoast_wpseo_opengraph-description":t["desc"],
              "_yoast_wpseo_twitter-title":t["seo"],"_yoast_wpseo_twitter-description":t["desc"]}
        try:
            base.req("/update-post",{"id":t["id"],"expected_modified_gmt":now["modified_gmt"],"title":t["title"],"content":content,"meta":meta})
        except Exception as ex:
            test=base.bridge_post(t["id"])
            if MARK+"-"+t["slug"] not in test.get("content",""):
                raise RuntimeError("Write unconfirmed, no auto-retry") from ex
        after=base.bridge_post(t["id"]);pub=base.public_post(t["id"]);seo=pub.get("yoast_head_json") or {}
        if (after.get("slug"),after.get("status"),after.get("title"),after.get("featured_media"))!=(
           t["slug"],"publish",t["title"],t["cover"]):
            raise RuntimeError("Post identity/title/media changed")
        if after["content"].count('id="'+MARK+"-"+t["slug"]+'"')!=1:
            raise RuntimeError("Human correction not saved")
        if seo.get("canonical")!=pub0["yoast_head_json"]["canonical"] or (seo.get("robots") or {}).get("index")=="noindex" or seo.get("description")!=t["desc"]:
            raise RuntimeError("SEO meta/canonical failed")
        if (seo.get("og_image") or [{}])[0].get("url")!=(pub0["yoast_head_json"].get("og_image") or [{}])[0].get("url"):
            raise RuntimeError("OG image changed")
        print("SECOND50_LIVE_VERIFIED",t["id"],after["link"],flush=True)
        time.sleep(1)
    print("A3TAL_SECOND50_HUMAN_REPAIR_TRIO_COMPLETE",flush=True)
